def calculate_gpa(total_marks, max_marks):
    """Calculate GPA on a 4.0 scale."""
    percentage = (total_marks / max_marks) * 100
    if percentage >= 85:
        return 4.0
    elif percentage >= 70:
        return 3.0
    elif percentage >= 55:
        return 2.0
    else:
        return 1.0

gpa = calculate_gpa(340, 400)
print(f"GPA: {gpa}")

def analyze_sales(sales_list):
    return min(sales_list), max(sales_list), sum(sales_list) / len(sales_list)

low, high, avg = analyze_sales([45000, 89000, 120000, 67000])
print(f"Low: {low}, High: {high}, Avg: {avg:.0f}")

def compute_efficiency_ratio(revenue, headcount):
    try:
        ratio = revenue / headcount
        return round(ratio, 2)
    except ZeroDivisionError:
        print("Warning: Employee headcount cannot be zero.")
        return 0.0

print("Ratio (10 Employees) : PKR", compute_efficiency_ratio(1500000, 10))
print("Ratio (0 Employees)  : PKR", compute_efficiency_ratio(1500000, 0))
